71 = 27\n\n# Calculate totals\ntotal_redemptions = redemptions_1969 + redemptions_1970 + redemptions_1971\ntotal_sales_with_discount = sales_plus_discount_1969 + sales_plus_discount_1970 + sales_plus_discount_1971\n\n# Calculate ratio\nratio = total_redemptions / total_sales_with_discount\n\nprint(f'Total Redemptions (1969-1971): {total_redemptions}')\nprint(f'Total Sales with Accrued Discount (1969-1971): {total_sales_with_discount}')\nprint(f'Ratio: {ratio}')\nprint(f'Rounded to 2 decimal places: {round(ratio, 2)}')\n\""}}},"_meta":{"goose_extension":"developer"}}],"metadata":{"userVisible":true,"agentVisible":true}}}
